def practice_section_scope(value,alias='q'):
    """Section IDs are opaque governed metadata; never inferred from chapter IDs."""
    if not re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]*',alias):raise ValueError('Invalid SQL scope alias')
